# Reconstruct the second demonstration from its repeated lattice and listed exceptional cells.
G2=[[2]*27 for _ in range(27)]
for r in range(27):
    for c in range(27):
        if c in (3,7,11,15,19,23): G2[r][c]=3
for r in (0,8,16,24):
    for c in range(27): G2[r][c]=3
exceptions={(0,15):0,(0,19):0,(8,7):4,(8,11):4,(8,15):0,(8,19):0,
            (16,7):4,(16,11):4,(16,15):1,(16,19):1,(24,15):1,(24,19):1}
for (r,c),v in exceptions.items(): G2[r][c]=v
out2=transform(G2)
out2
